182	inline int64_t ConvertToAclStorageOffset(const at::Tensor &at_tensor, const aclDataType acl_data_type)
183	{
184	    int64_t storageOffset = at_tensor.storage_offset();
185	    if (Is4BitDtype(acl_data_type)) {
186	        // ACL 4-bit descriptors express offsets in logical nibble elements.
187	        TORCH_CHECK(storageOffset <= INT64_MAX / FP4_IN_INT8,
188	                    "4-bit tensor storage offset is too large to convert to logical elements: ", storageOffset);
189	        storageOffset *= FP4_IN_INT8;
190	    }
