202	    const auto format = static_cast<aclFormat>(at_npu::native::get_npu_format(at_tensor));
203	    return (format == ACL_FORMAT_ND) || (format == ACL_FORMAT_NCHW) || (format == ACL_FORMAT_NHWC) ||
204	           (format == ACL_FORMAT_NCDHW);
