207	inline void CollectB4ShapeInfo(const at::Tensor &at_tensor, c10::SmallVector<int64_t, MAX_DIM_NUM> &wrapperStride,
208	                               c10::SmallVector<int64_t, MAX_DIM_NUM> &wrapperShape)
209	{
210	    int64_t nDim = at_tensor.sizes().size();
211	    if (nDim == 1) {
212	        wrapperShape[0] = wrapperShape[0] * FP4_IN_INT8;
213	    } else if (nDim > 1) {
214	        if (wrapperStride[nDim - 1] == 1 && wrapperStride[nDim - PENULTIMATE_DIM] == 1) {
215	            if (wrapperShape[nDim - PENULTIMATE_DIM] == 1) {
216	                wrapperStride[nDim - 1] = wrapperStride[nDim - 1] * FP4_IN_INT8;
217	                wrapperShape[nDim - PENULTIMATE_DIM] = wrapperShape[nDim - PENULTIMATE_DIM] * FP4_IN_INT8;
218	            } else if (wrapperShape[nDim - 1] == 1) {
219	                wrapperStride[nDim - PENULTIMATE_DIM] = wrapperStride[nDim - PENULTIMATE_DIM] * FP4_IN_INT8;
220	                wrapperShape[nDim - 1] = wrapperShape[nDim - 1] * FP4_IN_INT8;
221	            }
222	        } else if (wrapperStride[nDim - 1] == 1) {
223	            wrapperStride[nDim - PENULTIMATE_DIM] = wrapperStride[nDim - PENULTIMATE_DIM] * FP4_IN_INT8;
224	            wrapperShape[nDim - 1] = wrapperShape[nDim - 1] * FP4_IN_INT8;
225	        } else if (wrapperStride[nDim - PENULTIMATE_DIM] == 1) {
226	            wrapperStride[nDim - 1] = wrapperStride[nDim - 1] * FP4_IN_INT8;
227	            wrapperShape[nDim - PENULTIMATE_DIM] = wrapperShape[nDim - PENULTIMATE_DIM] * FP4_IN_INT8;
228	        }
229	
230	        for (auto i = 0; i < nDim - PENULTIMATE_DIM; i++) {
231	            wrapperStride[i] = wrapperStride[i] * FP4_IN_INT8;
232	        }
233	    } else {
234	        TORCH_CHECK(false, "unsupported tensor size() in 4-bit dtype.");
235	    }
236	}
