301	static inline void TryLoadCustOpApiFromEnv(const char *envName, const std::string &subDir,
302	    std::vector<void *> &handlers, std::set<std::string> &loadedPaths)
303	{
304	    const char *env = std::getenv(envName);
305	    if (env == nullptr) {
306	        return;
307	    }
308	    std::istringstream stream(env);
309	    std::string dir;
310	    while (std::getline(stream, dir, ':')) {
311	        if (dir.empty()) {
312	            continue;
313	        }
314	        std::string soPathStr = dir + subDir + GetCustOpApiLibName();
315	        char soPath[PATH_MAX] = {0};
316	        if (realpath(soPathStr.c_str(), soPath) == nullptr) {
317	            int errnoCopy = errno;
318	            ASCEND_LOGW("realpath failed for %s, errno=%d(%s).", soPathStr.c_str(), errnoCopy, strerror(errnoCopy));
319	            continue;
320	        }
321	        if (!loadedPaths.insert(soPath).second) {
322	            continue;
323	        }
324	        auto handler = dlopen(soPath, RTLD_LAZY);
325	        if (handler != nullptr) {
326	            handlers.push_back(handler);
327	        } else {
328	            ASCEND_LOGW("dlopen %s failed, error:%s.", soPath, dlerror());
329	        }
330	    }
331	}
