333	inline std::vector<void *> GetCustOpApiHandlers()
334	{
335	    std::vector<void *> handlers;
336	    std::set<std::string> loadedPaths;
337	    TryLoadCustOpApiFromEnv("ASCEND_CUSTOM_OPP_PATH", "/op_api/lib/", handlers, loadedPaths);
338	    TryLoadCustOpApiFromEnv("LD_LIBRARY_PATH", "/", handlers, loadedPaths);
339	
340	    if (handlers.empty()) {
341	        auto handler = GetOpApiLibHandler(GetCustOpApiLibName());
342	        if (handler != nullptr) {
343	            handlers.push_back(handler);
344	        }
345	    }
346	    return handlers;
347	}
