349	inline void *GetOpApiFuncAddr(const char *apiName)
350	{
351	    static auto custHandlers = GetCustOpApiHandlers();
352	    for (auto handler : custHandlers) {
353	        auto funcAddr = GetOpApiFuncAddrInLib(handler, GetCustOpApiLibName(), apiName);
354	        if (funcAddr != nullptr) {
355	            return funcAddr;
356	        }
357	    }
358	
359	    static auto transformerOpApiHandler = GetOpApiLibHandler(GetTransformerOpApiLibName());
360	    if (transformerOpApiHandler != nullptr) {
361	        auto funcAddr = GetOpApiFuncAddrInLib(transformerOpApiHandler, GetTransformerOpApiLibName(), apiName);
362	        if (funcAddr != nullptr) {
363	            return funcAddr;
364	        }
365	    }
366	    static auto opApiHandler = GetOpApiLibHandler(GetOpApiLibName());
367	    if (opApiHandler == nullptr) {
368	        return nullptr;
369	    }
370	    return GetOpApiFuncAddrInLib(opApiHandler, GetOpApiLibName(), apiName);
371	}
