373	inline c10::Scalar ConvertTensorToScalar(const at::Tensor &tensor)
374	{
375	    c10::Scalar expScalar;
376	    const at::Tensor *aclInput = &tensor;
377	    if (aclInput->scalar_type() == at::ScalarType::Double) {
378	        double value = *(double *)aclInput->data_ptr();
379	        c10::Scalar scalar(value);
380	        expScalar = scalar;
381	    } else if (aclInput->scalar_type() == at::ScalarType::Long) {
382	        int64_t value = *(int64_t *)aclInput->data_ptr();
383	        c10::Scalar scalar(value);
384	        expScalar = scalar;
385	    } else if (aclInput->scalar_type() == at::ScalarType::Float) {
386	        float value = *(float *)aclInput->data_ptr();
387	        c10::Scalar scalar(value);
388	        expScalar = scalar;
389	    } else if (aclInput->scalar_type() == at::ScalarType::Int) {
390	        int value = *(int *)aclInput->data_ptr();
391	        c10::Scalar scalar(value);
392	        expScalar = scalar;
393	    } else if (aclInput->scalar_type() == at::ScalarType::Half) {
394	        c10::Half value = *(c10::Half *)aclInput->data_ptr();
395	        c10::Scalar scalar(value);
396	        expScalar = scalar;
397	    } else if (aclInput->scalar_type() == at::ScalarType::Bool) {
398	        int8_t value = *(int8_t *)aclInput->data_ptr();
399	        c10::Scalar scalar(value);
400	        expScalar = scalar;
401	    } else if (aclInput->scalar_type() == at::ScalarType::ComplexDouble) {
402	        c10::complex<double> value = *(c10::complex<double> *)aclInput->data_ptr();
403	        c10::Scalar scalar(value);
404	        expScalar = scalar;
405	    } else if (aclInput->scalar_type() == at::ScalarType::ComplexFloat) {
406	        c10::complex<float> value = *(c10::complex<float> *)aclInput->data_ptr();
407	        c10::Scalar scalar(value);
408	        expScalar = scalar;
409	    } else if (aclInput->scalar_type() == at::ScalarType::BFloat16) {
410	        c10::BFloat16 value = *(c10::BFloat16 *)aclInput->data_ptr();
411	        c10::Scalar scalar(value);
412	        expScalar = scalar;
413	    } else {
414	        ASCEND_LOGE("unsupported scalar type! ");
415	    }
416	    return expScalar;
417	}
