432	inline aclTensor *ConvertType(const at::Tensor &at_tensor)
433	{
434	    static const auto aclCreateTensor = GET_OP_API_FUNC(aclCreateTensor);
435	    if (aclCreateTensor == nullptr) {
436	        return nullptr;
437	    }
438	
439	    if (!at_tensor.defined()) {
440	        return nullptr;
441	    }
442	    at::ScalarType scalar_data_type = at_tensor.scalar_type();
443	    aclDataType acl_data_type = ConvertToAclDataType(scalar_data_type);
444	    TORCH_CHECK(acl_data_type != ACL_DT_UNDEFINED,
445	                std::string(c10::toString(scalar_data_type)) + " has not been supported")
446	    std::vector<int64_t> storageDims;
447	    c10::SmallVector<int64_t, MAX_DIM_NUM> wrapperStride = op_infer::array_to_small_vector(at_tensor.strides());
448	    c10::SmallVector<int64_t, MAX_DIM_NUM> wrapperShape = op_infer::array_to_small_vector(at_tensor.sizes());
449	
450	    const auto dimNum = at_tensor.sizes().size();
451	    aclFormat format = ACL_FORMAT_ND;
452	    const bool isBaseFormat = IsOpInputBaseFormat(at_tensor);
453	    if (!isBaseFormat) {
454	        format = static_cast<aclFormat>(at_npu::native::get_npu_format(at_tensor));
455	        if (acl_data_type != ACL_STRING) {
456	            TORCH_CHECK(at_tensor.itemsize() > 0, "the itemsize of tensor must be greater than 0.");
457	            storageDims = at_npu::native::get_npu_storage_sizes(at_tensor);
458	        }
459	    } else {
460	        switch (dimNum) {
461	            case 3:
462	                format = ACL_FORMAT_NCL;
463	                break;
464	            case 4:
465	                format = ACL_FORMAT_NCHW;
466	                break;
467	            case 5:
468	                format = ACL_FORMAT_NCDHW;
469	                break;
470	            default:
471	                format = ACL_FORMAT_ND;
472	        }
473	        if (acl_data_type != ACL_STRING) {
474	            TORCH_CHECK(at_tensor.itemsize() > 0, "the itemsize of tensor must be greater than 0.");
475	            storageDims.push_back(at_tensor.storage().nbytes() / at_tensor.itemsize());
476	        }
477	    }
478	
479	    if (acl_data_type != ACL_STRING && Is4BitDtype(acl_data_type)) {
480	        CollectB4ShapeInfo(at_tensor, wrapperStride, wrapperShape);
481	        storageDims.back() *= FP4_IN_INT8;
482	        if (!isBaseFormat) {
483	            auto realFormat = FORMAT_FAKE_TO_REAL.find(format);
484	            TORCH_CHECK(realFormat != FORMAT_FAKE_TO_REAL.end(), "not support convert ", format, ".");
485	            format = realFormat->second;
486	        }
487	    }
488	
489	    if (at_tensor.unsafeGetTensorImpl()->is_wrapped_number()) {
490	        c10::Scalar expScalar = ConvertTensorToScalar(at_tensor);
491	        at::Tensor aclInput = CopyScalarToDevice(expScalar, scalar_data_type);
492	        return aclCreateTensor(aclInput.sizes().data(), aclInput.sizes().size(), acl_data_type,
493	                               aclInput.strides().data(), aclInput.storage_offset(), format, storageDims.data(),
494	                               storageDims.size(), const_cast<void *>(aclInput.storage().data()));
495	    }
496	
497	    auto acl_tensor =
498	        aclCreateTensor(wrapperShape.data(), at_tensor.sizes().size(), acl_data_type, wrapperStride.data(),
499	                        ConvertToAclStorageOffset(at_tensor, acl_data_type), format, storageDims.data(),
500	                        storageDims.size(), const_cast<void *>(at_tensor.storage().data()));
501	    return acl_tensor;
502	}
