977	inline void ApplyDeterministicConfig()
978	{
979	    constexpr bool kUseOpApiPath = true; // isOpapi=true: 走 opapi 路径下发，aclnn_common.h 全场景均为 opapi
980	    auto deterministicAlgorithmsStatus = at::globalContext().deterministicAlgorithms();
981	    auto applyLevelFn = at_npu::native::ApplyDeterministicLevel;
982	    auto getLevelFn = c10_npu::GetDeterministicLevel;
983	    if (applyLevelFn != nullptr && getLevelFn != nullptr) {
984	        int64_t level = static_cast<int64_t>(getLevelFn());
985	        applyLevelFn(level, deterministicAlgorithmsStatus, kUseOpApiPath);
986	        return;
987	    }
988	    static bool fallbackWarned = false;
989	    if (!fallbackWarned) {
990	        fallbackWarned = true;
991	        if (applyLevelFn == nullptr && getLevelFn == nullptr) {
992	            ASCEND_LOGW("ApplyDeterministicLevel and GetDeterministicLevel are both missing in torch_npu, "
993	                        "fallback to ACL_OPT_DETERMINISTIC binary switch, deterministic_level will be ignored.");
994	        } else if (applyLevelFn == nullptr) {
995	            ASCEND_LOGW("ApplyDeterministicLevel is missing in torch_npu, "
996	                        "fallback to ACL_OPT_DETERMINISTIC binary switch, deterministic_level will be ignored.");
997	        } else {
998	            ASCEND_LOGW("GetDeterministicLevel is missing in torch_npu, "
999	                        "fallback to ACL_OPT_DETERMINISTIC binary switch, deterministic_level will be ignored.");
1000	        }
1001	    }
1002	    aclError ret = aclrtCtxSetSysParamOpt(aclSysParamOpt::ACL_OPT_DETERMINISTIC, deterministicAlgorithmsStatus ? 1 : 0);
1003	    if (ret != ACL_SUCCESS) {
1004	        ASCEND_LOGW("aclrtCtxSetSysParamOpt(ACL_OPT_DETERMINISTIC) failed, ret=%d, "
1005	                    "deterministic config may be incorrect.",
1006	                    static_cast<int>(ret));
1007	    }
1008	}
