1010	#define ACLNN_CMD(aclnn_api, ...) \
1011	    do { \
1012	        auto device = DecodeDevice(__VA_ARGS__); \
1013	        const c10::OptionalDeviceGuard device_guard(device); \
1014	        static const auto getWorkspaceSizeFuncAddr = GetOpApiFuncAddr(#aclnn_api "GetWorkspaceSize"); \
1015	        static const auto opApiFuncAddr = GetOpApiFuncAddr(#aclnn_api); \
1016	        static const auto initMemAddr = GetOpApiFuncAddr("InitHugeMemThreadLocal"); \
1017	        static const auto unInitMemAddr = GetOpApiFuncAddr("UnInitHugeMemThreadLocal"); \
1018	        static const auto releaseMemAddr = GetOpApiFuncAddr("ReleaseHugeMem"); \
1019	        TORCH_CHECK(getWorkspaceSizeFuncAddr != nullptr && opApiFuncAddr != nullptr, #aclnn_api, " or ", \
1020	                    #aclnn_api "GetWorkspaceSize", " not in ", GetOpApiLibName(), ", or ", GetOpApiLibName(), ", or ", \
1021	                    GetTransformerOpApiLibName(), "not found."); \
1022	        auto acl_stream = c10_npu::getCurrentNPUStream().stream(false); \
1023	        uint64_t workspace_size = 0; \
1024	        uint64_t *workspace_size_addr = &workspace_size; \
1025	        aclOpExecutor *executor = nullptr; \
1026	        aclOpExecutor **executor_addr = &executor; \
1027	        InitHugeMemThreadLocal initMemFunc = reinterpret_cast<InitHugeMemThreadLocal>(initMemAddr); \
1028	        UnInitHugeMemThreadLocal unInitMemFunc = reinterpret_cast<UnInitHugeMemThreadLocal>(unInitMemAddr); \
1029	        if (initMemFunc) { \
1030	            initMemFunc(nullptr, false); \
1031	        } \
1032	        ApplyDeterministicConfig(); \
1033	        auto converted_params = ConvertTypes(__VA_ARGS__, workspace_size_addr, executor_addr); \
1034	        static auto getWorkspaceSizeFunc = ConvertToOpApiFunc(converted_params, getWorkspaceSizeFuncAddr); \
1035	        auto workspace_status = call(getWorkspaceSizeFunc, converted_params); \
1036	        if (workspace_status != 0) { \
1037	            ReleaseConvertTypes(converted_params); \
1038	            TORCH_CHECK(false, "call " #aclnn_api " failed, detail:", aclGetRecentErrMsg()); \
1039	        } \
1040	        at::Tensor workspace_tensor; \
1041	        void *workspace_addr = nullptr; \
1042	        if (workspace_size != 0) { \
1043	            at::TensorOptions options = at::TensorOptions(torch_npu::utils::get_npu_device_type()); \
1044	            workspace_tensor = at::empty({workspace_size}, options.dtype(at::kByte)); \
1045	            workspace_addr = const_cast<void *>(workspace_tensor.storage().data()); \
1046	        } \
1047	        auto acl_call = [converted_params, workspace_addr, workspace_size, acl_stream, executor]() -> int { \
1048	            typedef int (*OpApiFunc)(void *, uint64_t, aclOpExecutor *, const aclrtStream); \
1049	            OpApiFunc opApiFunc = reinterpret_cast<OpApiFunc>(opApiFuncAddr); \
1050	            auto api_ret = opApiFunc(workspace_addr, workspace_size, executor, acl_stream); \
1051	            ReleaseConvertTypes(converted_params); \
1052	            ReleaseHugeMem releaseMemFunc = reinterpret_cast<ReleaseHugeMem>(releaseMemAddr); \
1053	            if (releaseMemFunc) { \
1054	                releaseMemFunc(nullptr, false); \
1055	            } \
1056	            TORCH_CHECK(api_ret == 0, "call " #aclnn_api " failed, detail:", aclGetRecentErrMsg()); \
1057	            return api_ret; \
1058	        }; \
1059	        at_npu::native::OpCommand cmd; \
1060	        cmd.Name(#aclnn_api); \
1061	        cmd.SetCustomHandler(acl_call); \
1062	        cmd.Run(); \
1063	        if (unInitMemFunc) { \
1064	            unInitMemFunc(nullptr, false); \
1065	        } \
1066	    } while (false)
